CREATE OR REPLACE FUNCTION private.izytel_phase4_notification_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_changed boolean := false;
  v_is_reassignment boolean := false;
  v_type text;
  v_title text;
  v_body text;
  v_staff record;
begin
  begin
    if tg_op = 'INSERT' then
      v_changed := true;
    else
      v_changed := old.assignment_state is distinct from new.assignment_state
        or old.assigned_agent_id is distinct from new.assigned_agent_id
        or old.assigned_at is distinct from new.assigned_at;
    end if;

    if new.assignment_state = 'assigned'
       and nullif(btrim(coalesce(new.assigned_agent_id, '')), '') is not null
       and v_changed then
      v_is_reassignment := new.last_refused_agent_id is not null;
      if tg_op = 'UPDATE' and old.assigned_agent_id is distinct from new.assigned_agent_id then
        v_is_reassignment := true;
      end if;
      v_type := case when v_is_reassignment then 'order_reassigned' else 'order_assigned' end;
      v_title := case when v_is_reassignment then 'Commande reaffectee' else 'Nouvelle commande' end;
      v_body := new.order_reference || ' - ' || upper(coalesce(new.network, '')) ||
        ' - ' || new.amount::text || ' F';

      perform private.enqueue_izytel_notification(
        new.assigned_agent_id,
        v_type,
        v_title,
        v_body,
        jsonb_build_object(
          'type', v_type,
          'orderId', new.order_id,
          'orderReference', new.order_reference,
          'route', 'order_detail',
          'assignmentMode', coalesce(new.assignment_mode, 'automatic')
        ),
        'order:' || new.order_id || ':assigned:' || new.assigned_agent_id || ':' ||
          coalesce(extract(epoch from new.assigned_at)::text, extract(epoch from new.updated_at)::text)
      );
    end if;

    if new.assignment_state = 'manual_required' then
      if tg_op = 'INSERT' then
        v_changed := true;
      else
        v_changed := old.assignment_state is distinct from 'manual_required';
      end if;
      if v_changed then
        v_body := new.order_reference || ' - ' || upper(coalesce(new.network, '')) ||
          ' - ' || new.amount::text || ' F';
        for v_staff in
          select s.firebase_uid
          from public.izytel_staff_access s
          where s.firebase_uid in (select private.izytel_notification_zone_recipients(new.zone_id))
        loop
          perform private.enqueue_izytel_notification(
            v_staff.firebase_uid,
            'order_manual_required',
            'Affectation manuelle requise',
            v_body,
            jsonb_build_object(
              'type', 'order_manual_required',
              'orderId', new.order_id,
              'orderReference', new.order_reference,
              'route', 'order_detail'
            ),
            'order:' || new.order_id || ':manual:' || v_staff.firebase_uid || ':' ||
              extract(epoch from new.updated_at)::text
          );
        end loop;
      end if;
    end if;
  exception when others then
    raise warning '[IzyTel Notifications][phase4] %', sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.izytel_record_order_economics_observation(p_order_id text, p_acquisition_source text DEFAULT 'izytel'::text, p_executor_type text DEFAULT 'agent'::text, p_executor_id text DEFAULT NULL::text, p_referring_cabiniste_id text DEFAULT NULL::text, p_manager_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_order public.phase4_assignment_orders%rowtype;
  v_existing public.order_economics%rowtype;
  v_calc jsonb;
  v_order_id text := nullif(btrim(coalesce(p_order_id, '')), '');
  v_acquisition_source text := lower(btrim(coalesce(p_acquisition_source, 'izytel')));
  v_executor_type text := lower(btrim(coalesce(p_executor_type, 'agent')));
  v_executor_id text := nullif(btrim(coalesce(p_executor_id, '')), '');
  v_referring_cabiniste_id text := nullif(btrim(coalesce(p_referring_cabiniste_id, '')), '');
  v_manager_id text := nullif(btrim(coalesce(p_manager_id, '')), '');
begin
  if v_order_id is null then
    raise exception 'ORDER_ID_REQUIRED';
  end if;

  select *
    into v_order
  from public.phase4_assignment_orders
  where order_id = v_order_id;

  if not found then
    raise exception 'PHASE4_ORDER_NOT_FOUND';
  end if;

  if v_order.order_status <> 'completed' then
    raise exception 'ORDER_NOT_COMPLETED';
  end if;

  if v_executor_type = 'agent' and v_executor_id is null then
    v_executor_id := nullif(btrim(coalesce(v_order.assigned_agent_id, '')), '');
  end if;

  if v_executor_id is null then
    raise exception 'EXECUTOR_REQUIRED';
  end if;

  select *
    into v_existing
  from public.order_economics
  where order_id = v_order_id;

  if found then
    if v_existing.acquisition_source is distinct from v_acquisition_source
       or v_existing.executor_type is distinct from v_executor_type
       or v_existing.executor_id is distinct from v_executor_id
       or v_existing.referring_cabiniste_id is distinct from v_referring_cabiniste_id
       or v_existing.manager_id is distinct from v_manager_id
       or v_existing.network is distinct from lower(btrim(v_order.network))
       or v_existing.order_amount is distinct from v_order.amount::bigint then
      raise exception 'ORDER_ECONOMICS_CONTEXT_MISMATCH';
    end if;

    return to_jsonb(v_existing) || jsonb_build_object(
      'idempotent', true,
      'observation_mode', true
    );
  end if;

  v_calc := private.izytel_calculate_order_economics(
    v_order.network,
    v_order.amount::bigint,
    v_acquisition_source,
    v_executor_type,
    v_executor_id,
    v_referring_cabiniste_id,
    v_manager_id
  );

  insert into public.order_economics (
    order_id,
    order_reference,
    network,
    order_amount,
    acquisition_source,
    executor_type,
    executor_id,
    referring_cabiniste_id,
    manager_id,
    economic_policy_id,
    telecom_margin_bps,
    telecom_margin_amount,
    customer_fee_amount,
    cabiniste_margin_share_bps,
    cabiniste_margin_amount,
    izytel_margin_amount,
    cabiniste_settlement_amount,
    izytel_gross_gain,
    economic_status,
    computed_at
  ) values (
    v_order.order_id,
    v_order.order_reference,
    v_calc->>'network',
    (v_calc->>'order_amount')::bigint,
    v_calc->>'acquisition_source',
    v_calc->>'executor_type',
    v_calc->>'executor_id',
    nullif(v_calc->>'referring_cabiniste_id', ''),
    nullif(v_calc->>'manager_id', ''),
    v_calc->>'economic_policy_id',
    (v_calc->>'telecom_margin_bps')::integer,
    (v_calc->>'telecom_margin_amount')::bigint,
    (v_calc->>'customer_fee_amount')::bigint,
    (v_calc->>'cabiniste_margin_share_bps')::integer,
    (v_calc->>'cabiniste_margin_amount')::bigint,
    (v_calc->>'izytel_margin_amount')::bigint,
    (v_calc->>'cabiniste_settlement_amount')::bigint,
    (v_calc->>'izytel_gross_gain')::bigint,
    'pending',
    now()
  );

  select *
    into v_existing
  from public.order_economics
  where order_id = v_order_id;

  return to_jsonb(v_existing) || jsonb_build_object(
    'idempotent', false,
    'observation_mode', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.phase4_fill_history_order_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
