    new.payment_status := coalesce(new.payment_status, v_order.payment_status);
    new.firebase_created_at := coalesce(new.firebase_created_at, v_order.firebase_created_at);
    new.paid_at := coalesce(new.paid_at, v_order.paid_at);
  end if;
